import{_ as t,c as d,o,ae as r}from"./chunks/framework.DCU7Csu6.js";const u=JSON.parse('{"title":"EPIC 43: Reports Type & Schema Fixes — ExciseReportRequest bug, MeasurementPenalties/WHM drift, missing types, Promise<unknown>","description":"","frontmatter":{},"headers":[],"relativePath":"epics/EPIC_43_REPORTS_TYPE_SCHEMA_FIXES.md","filePath":"epics/EPIC_43_REPORTS_TYPE_SCHEMA_FIXES.md"}'),a={name:"epics/EPIC_43_REPORTS_TYPE_SCHEMA_FIXES.md"};function s(n,e,c,i,l,p){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="epic-43-reports-type-schema-fixes-—-excisereportrequest-bug-measurementpenalties-whm-drift-missing-types-promise-unknown" tabindex="-1">EPIC 43: Reports Type &amp; Schema Fixes — ExciseReportRequest bug, MeasurementPenalties/WHM drift, missing types, Promise&lt;unknown&gt; <a class="header-anchor" href="#epic-43-reports-type-schema-fixes-—-excisereportrequest-bug-measurementpenalties-whm-drift-missing-types-promise-unknown" aria-label="Permalink to &quot;EPIC 43: Reports Type &amp; Schema Fixes — ExciseReportRequest bug, MeasurementPenalties/WHM drift, missing types, Promise\\&lt;unknown\\&gt;&quot;">​</a></h1><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>EPIC</strong></td><td>43</td></tr><tr><td><strong>Module</strong></td><td>Reports (<code>src/modules/reports/</code>)</td></tr><tr><td><strong>Priority</strong></td><td>High</td></tr><tr><td><strong>Target SDK Version</strong></td><td>v2.7.x</td></tr><tr><td><strong>Backlog Task</strong></td><td>task-43</td></tr><tr><td><strong>Depends On</strong></td><td>None (standalone type fixes)</td></tr><tr><td><strong>Blocks</strong></td><td>task-44 (Reports New &amp; Removed Endpoints), task-45 (Reports Code Quality)</td></tr><tr><td><strong>Source</strong></td><td>February 2026 Swagger Audit</td></tr><tr><td><strong>Swagger</strong></td><td><code>wildberries_api_doc/12-reports.yaml</code></td></tr><tr><td><strong>Related Stories</strong></td><td>3.7 (Reports Generation &amp; Retrieval), 4.4 (Reports Generation &amp; Retrieval)</td></tr><tr><td><strong>Related QA Gates</strong></td><td>3.7, 4.4</td></tr></tbody></table><hr><h2 id="current-state" tabindex="-1">Current State <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current State&quot;">​</a></h2><h3 id="what-exists" tabindex="-1">What Exists <a class="header-anchor" href="#what-exists" aria-label="Permalink to &quot;What Exists&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Asset</th><th>Path</th><th>Details</th></tr></thead><tbody><tr><td>Module implementation</td><td><code>src/modules/reports/index.ts</code></td><td>507 lines, 26 methods</td></tr><tr><td>Types file</td><td><code>src/types/reports.types.ts</code></td><td>479 lines, 18 interfaces + 2 type aliases</td></tr><tr><td>Rate limits</td><td><code>src/config/reports-rate-limits.ts</code></td><td>147 lines, 25 rate limit entries</td></tr><tr><td>Unit tests</td><td>(none)</td><td>No dedicated test file exists yet</td></tr><tr><td>Swagger spec</td><td><code>wildberries_api_doc/12-reports.yaml</code></td><td>26 endpoints, 20 schemas</td></tr></tbody></table><h3 id="what-is-wrong" tabindex="-1">What Is Wrong <a class="header-anchor" href="#what-is-wrong" aria-label="Permalink to &quot;What Is Wrong&quot;">​</a></h3><p>Eight issues have been identified in the reports module types:</p><ol><li><p><strong>ExciseReportRequest.countries union/array precedence bug (HIGH)</strong>: The current type is defined as <code>&#39;AM&#39; | &#39;BY&#39; | &#39;KG&#39; | &#39;KZ&#39; | &#39;RU&#39; | &#39;UZ&#39;[]</code>. Due to TypeScript operator precedence, only the last variant <code>&#39;UZ&#39;</code> becomes an array element type -- the type parses as <code>&#39;AM&#39; | &#39;BY&#39; | &#39;KG&#39; | &#39;KZ&#39; | &#39;RU&#39; | (&#39;UZ&#39;[])</code> instead of an array of the union. The swagger defines this as <code>type: array, items: { type: string, enum: [AM, BY, KG, KZ, RU, UZ] }</code>, meaning the entire value should be an array of enum strings. This is the same class of bug as analytics <code>AvailabilityFilters</code> (EPIC 41).</p></li><li><p><strong>Penalty/MeasurementPenalties schema drift (HIGH)</strong>: The SDK <code>Penalty</code> interface has diverged from the swagger <code>MeasurementPenalties</code> schema. Missing field: <code>subjectName</code> (string, &quot;Predmet&quot;). Naming mismatch: SDK uses <code>totalCount</code> while swagger uses <code>total</code>. The SDK <code>Penalty</code> type also retains <code>subject</code> (old name) instead of <code>subjectName</code>.</p></li><li><p><strong>Measurement/WHM schema drift (HIGH)</strong>: The SDK <code>Measurement</code> interface contains stale fields <code>dateStart</code> and <code>dateEnd</code> that do not exist in the current swagger <code>WHM</code> schema. The WHM schema has only a single <code>dt</code> field for date/time. Additionally, <code>subjectName</code> is missing from the SDK type. SDK uses <code>totalCount</code> while swagger uses <code>total</code>. SDK also has <code>prcOver</code>, <code>volumeSup</code>, <code>widthSup</code>, <code>lengthSup</code>, <code>heightSup</code> fields that are not in the WHM schema (those belong only to MeasurementPenalties).</p></li><li><p><strong>8 methods return Promise&lt;unknown&gt; (HIGH)</strong>: The following methods lack proper response types: <code>getAnalyticsAntifraudDetails</code>, <code>getAnalyticsIncorrectAttachments</code>, <code>getAnalyticsGoodsLabeling</code>, <code>getAnalyticsCharacteristicsChange</code>, <code>getAnalyticsRegionSale</code>, <code>getBrandShareBrands</code>, <code>getBrandShareParentSubjects</code>, <code>getAnalyticsBrandShare</code>. Of these, 6 are targeted by task-43 AC #4 (excluding <code>getAnalyticsIncorrectAttachments</code> and <code>getAnalyticsCharacteristicsChange</code> which may be addressed in task-44).</p></li><li><p><strong>Missing error types (MEDIUM)</strong>: <code>Response400Retentions</code> and <code>Response403Retentions</code> schemas exist in the swagger (used by penalty, measurement, and deduction endpoints) but are not present in the SDK types file.</p></li><li><p><strong>Stale error types (LOW)</strong>: <code>Response400WHM</code> and <code>Response403WHM</code> exist in the SDK types file but are not referenced by any current swagger schema. The swagger now uses <code>Response400Retentions</code> and <code>Response403Retentions</code> for both penalty and measurement endpoints.</p></li><li><p><strong>Inline type literals in 5 methods (MEDIUM)</strong>: Five methods use inline object types instead of named interfaces, reducing reusability and readability:</p><ul><li><code>getTasksDownload</code> (warehouse remains download -- 8 fields with nested <code>warehouses</code> array)</li><li><code>getTasksDownload2</code> (acceptance report download -- 7 fields)</li><li><code>getBannedProductsBlocked</code> (blocked products -- nested <code>report</code> array with 5 fields)</li><li><code>getBannedProductsShadowed</code> (shadowed products -- nested <code>report</code> array with 5 fields)</li><li><code>getAnalyticsGoodsReturn</code> (goods return -- nested <code>report</code> array with 19 fields)</li></ul></li><li><p><strong>All changes must pass TypeScript strict compilation</strong>: Zero errors under <code>npx tsc --noEmit</code> with strict mode enabled.</p></li></ol><h3 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h3><ul><li><strong>ExciseReportRequest silently accepts wrong data</strong>: The malformed union means TypeScript will accept a bare string <code>&#39;AM&#39;</code> where an array is expected, causing runtime type mismatches with the API. Sellers generating excise reports for multiple countries will get incorrect results.</li><li><strong>Penalty/Measurement schema drift breaks consumers</strong>: The <code>totalCount</code> field does not exist in the API response -- only <code>total</code> does. SDK consumers reading <code>totalCount</code> will get <code>undefined</code>.</li><li><strong>Stale fields cause confusion</strong>: <code>dateStart</code>/<code>dateEnd</code> in the Measurement type do not come from the API, leading developers to expect data that never arrives.</li><li><strong>Promise&lt;unknown&gt; defeats SDK purpose</strong>: Six active methods provide zero type safety, forcing consumers to cast or use <code>as any</code> for antifraud details, goods labeling, region sales, and brand share reports.</li><li><strong>Missing error types</strong>: Retentions error responses (400/403) cannot be properly typed in catch blocks, reducing error handling quality.</li><li><strong>Inline types reduce maintainability</strong>: Five methods with complex inline object types are difficult to document, test, and reuse.</li></ul><hr><h2 id="gap-analysis" tabindex="-1">Gap Analysis <a class="header-anchor" href="#gap-analysis" aria-label="Permalink to &quot;Gap Analysis&quot;">​</a></h2><h3 id="excisereportrequest-countries-type-comparison" tabindex="-1">ExciseReportRequest.countries Type Comparison <a class="header-anchor" href="#excisereportrequest-countries-type-comparison" aria-label="Permalink to &quot;ExciseReportRequest.countries Type Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Current (Malformed)</th><th>Correct (Per Swagger)</th></tr></thead><tbody><tr><td><code>&#39;AM&#39; | &#39;BY&#39; | &#39;KG&#39; | &#39;KZ&#39; | &#39;RU&#39; | &#39;UZ&#39;[]</code></td><td><code>(&#39;AM&#39; | &#39;BY&#39; | &#39;KG&#39; | &#39;KZ&#39; | &#39;RU&#39; | &#39;UZ&#39;)[]</code></td></tr><tr><td>Only <code>&#39;UZ&#39;</code> is treated as array element</td><td>Entire union is the array element type</td></tr><tr><td>Accepts bare strings -- wrong</td><td>Only accepts array of enum values -- correct</td></tr></tbody></table><h3 id="penalty-measurementpenalties-field-comparison" tabindex="-1">Penalty / MeasurementPenalties Field Comparison <a class="header-anchor" href="#penalty-measurementpenalties-field-comparison" aria-label="Permalink to &quot;Penalty / MeasurementPenalties Field Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>SDK <code>Penalty</code></th><th>Swagger <code>MeasurementPenalties</code></th><th>Action</th></tr></thead><tbody><tr><td><code>nmId</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>subjectName</code></td><td><strong>MISSING</strong></td><td><code>string</code> (&quot;Predmet&quot;)</td><td><strong>ADD</strong></td></tr><tr><td><code>subject</code></td><td><code>string</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (replaced by <code>subjectName</code>)</td></tr><tr><td><code>dimId</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>prcOver</code></td><td><code>number</code></td><td><code>number</code></td><td>OK</td></tr><tr><td><code>volume</code></td><td><code>number</code></td><td><code>number</code></td><td>OK</td></tr><tr><td><code>width</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>length</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>height</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>volumeSup</code></td><td><code>number</code></td><td><code>number</code></td><td>OK</td></tr><tr><td><code>widthSup</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>lengthSup</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>heightSup</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>photoUrls</code></td><td><code>string[]</code></td><td><code>string[]</code></td><td>OK</td></tr><tr><td><code>dtBonus</code></td><td><code>string</code></td><td><code>string (date-time)</code></td><td>OK</td></tr><tr><td><code>isValid</code></td><td><code>boolean</code></td><td><code>boolean</code></td><td>OK</td></tr><tr><td><code>isValidDt</code></td><td><code>string</code></td><td><code>string (date-time)</code></td><td>OK</td></tr><tr><td><code>reversalAmount</code></td><td><code>number</code></td><td><code>number</code></td><td>OK</td></tr><tr><td><code>penaltyAmount</code></td><td><code>number</code></td><td><code>number</code></td><td>OK</td></tr><tr><td><code>data.totalCount</code></td><td><code>number</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>RENAME to <code>total</code></strong></td></tr><tr><td><code>data.total</code></td><td><strong>MISSING</strong></td><td><code>integer</code></td><td><strong>ADD</strong> (replaces <code>totalCount</code>)</td></tr></tbody></table><h3 id="measurement-whm-field-comparison" tabindex="-1">Measurement / WHM Field Comparison <a class="header-anchor" href="#measurement-whm-field-comparison" aria-label="Permalink to &quot;Measurement / WHM Field Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>SDK <code>Measurement</code></th><th>Swagger <code>WHM</code></th><th>Action</th></tr></thead><tbody><tr><td><code>nmId</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>subjectName</code></td><td><strong>MISSING</strong></td><td><code>string</code> (&quot;Predmet&quot;)</td><td><strong>ADD</strong></td></tr><tr><td><code>subject</code></td><td><code>string</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong></td></tr><tr><td><code>dimId</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>prcOver</code></td><td><code>number</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (only in MeasurementPenalties)</td></tr><tr><td><code>volume</code></td><td><code>number</code></td><td><code>number</code></td><td>OK</td></tr><tr><td><code>width</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>length</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>height</code></td><td><code>number</code></td><td><code>integer</code></td><td>OK</td></tr><tr><td><code>volumeSup</code></td><td><code>number</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (only in MeasurementPenalties)</td></tr><tr><td><code>widthSup</code></td><td><code>number</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (only in MeasurementPenalties)</td></tr><tr><td><code>lengthSup</code></td><td><code>number</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (only in MeasurementPenalties)</td></tr><tr><td><code>heightSup</code></td><td><code>number</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (only in MeasurementPenalties)</td></tr><tr><td><code>photoUrls</code></td><td><code>string[]</code></td><td><code>string[]</code></td><td>OK</td></tr><tr><td><code>dt</code></td><td><code>string</code></td><td><code>string (date-time)</code></td><td>OK</td></tr><tr><td><code>dateStart</code></td><td><code>string</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (stale)</td></tr><tr><td><code>dateEnd</code></td><td><code>string</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>REMOVE</strong> (stale)</td></tr><tr><td><code>data.totalCount</code></td><td><code>number</code></td><td><strong>NOT IN SCHEMA</strong></td><td><strong>RENAME to <code>total</code></strong></td></tr><tr><td><code>data.total</code></td><td><strong>MISSING</strong></td><td><code>integer</code></td><td><strong>ADD</strong> (replaces <code>totalCount</code>)</td></tr></tbody></table><h3 id="methods-returning-promise-unknown" tabindex="-1">Methods Returning Promise&lt;unknown&gt; <a class="header-anchor" href="#methods-returning-promise-unknown" aria-label="Permalink to &quot;Methods Returning Promise\\&lt;unknown\\&gt;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Current Return Type</th><th>Required Return Type</th><th>Endpoint</th></tr></thead><tbody><tr><td><code>getAnalyticsAntifraudDetails</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/antifraud-details</code></td></tr><tr><td><code>getAnalyticsIncorrectAttachments</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/incorrect-attachments</code></td></tr><tr><td><code>getAnalyticsGoodsLabeling</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/goods-labeling</code></td></tr><tr><td><code>getAnalyticsCharacteristicsChange</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/characteristics-change</code></td></tr><tr><td><code>getAnalyticsRegionSale</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/region-sale</code></td></tr><tr><td><code>getBrandShareBrands</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/brand-share/brands</code></td></tr><tr><td><code>getBrandShareParentSubjects</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/brand-share/parent-subjects</code></td></tr><tr><td><code>getAnalyticsBrandShare</code></td><td><code>Promise&lt;unknown&gt;</code></td><td>Needs new interface</td><td><code>/api/v1/analytics/brand-share</code></td></tr></tbody></table><p><strong>Note</strong>: task-43 AC #4 targets 6 of these 8 methods (excluding <code>getAnalyticsIncorrectAttachments</code> and <code>getAnalyticsCharacteristicsChange</code> which may be scoped to task-44).</p><h3 id="missing-error-types" tabindex="-1">Missing Error Types <a class="header-anchor" href="#missing-error-types" aria-label="Permalink to &quot;Missing Error Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Schema Name</th><th>Purpose</th><th>Used By</th></tr></thead><tbody><tr><td><code>Response400Retentions</code></td><td>400 error for retentions endpoints (title, status, detail, requestId, origin)</td><td><code>getMeasurementPenalties</code>, <code>getWarehouseMeasurements</code>, <code>getDeductions</code></td></tr><tr><td><code>Response403Retentions</code></td><td>403 error for retentions endpoints (title, status, detail, requestId, origin)</td><td><code>getMeasurementPenalties</code>, <code>getWarehouseMeasurements</code>, <code>getDeductions</code></td></tr></tbody></table><h3 id="stale-types" tabindex="-1">Stale Types <a class="header-anchor" href="#stale-types" aria-label="Permalink to &quot;Stale Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type Name</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td><code>Response400WHM</code></td><td>Not in current swagger</td><td>Mark <code>@deprecated</code> or remove</td></tr><tr><td><code>Response403WHM</code></td><td>Not in current swagger</td><td>Mark <code>@deprecated</code> or remove</td></tr></tbody></table><h3 id="inline-type-literals-requiring-extraction" tabindex="-1">Inline Type Literals Requiring Extraction <a class="header-anchor" href="#inline-type-literals-requiring-extraction" aria-label="Permalink to &quot;Inline Type Literals Requiring Extraction&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Inline Type Location</th><th>Proposed Interface Name</th></tr></thead><tbody><tr><td><code>getTasksDownload</code></td><td>Return type (warehouse remains)</td><td><code>WarehouseRemainsDownloadItem</code></td></tr><tr><td><code>getTasksDownload2</code></td><td>Return type (acceptance report)</td><td><code>AcceptanceReportDownloadItem</code></td></tr><tr><td><code>getBannedProductsBlocked</code></td><td>Return type (blocked products)</td><td><code>BannedProductsBlockedResponse</code></td></tr><tr><td><code>getBannedProductsShadowed</code></td><td>Return type (shadowed products)</td><td><code>BannedProductsShadowedResponse</code></td></tr><tr><td><code>getAnalyticsGoodsReturn</code></td><td>Return type (goods return)</td><td><code>GoodsReturnResponse</code></td></tr></tbody></table><hr><h2 id="implementation-approach" tabindex="-1">Implementation Approach <a class="header-anchor" href="#implementation-approach" aria-label="Permalink to &quot;Implementation Approach&quot;">​</a></h2><h3 id="step-1-fix-excisereportrequest-countries-type" tabindex="-1">Step 1: Fix ExciseReportRequest.countries Type <a class="header-anchor" href="#step-1-fix-excisereportrequest-countries-type" aria-label="Permalink to &quot;Step 1: Fix ExciseReportRequest.countries Type&quot;">​</a></h3><p>Change the type from the malformed union <code>&#39;AM&#39; | &#39;BY&#39; | &#39;KG&#39; | &#39;KZ&#39; | &#39;RU&#39; | &#39;UZ&#39;[]</code> to the correctly parenthesized array type <code>(&#39;AM&#39; | &#39;BY&#39; | &#39;KG&#39; | &#39;KZ&#39; | &#39;RU&#39; | &#39;UZ&#39;)[]</code>. This ensures the entire union is the element type of the array, matching the swagger <code>type: array, items: { type: string, enum: [...] }</code> definition.</p><h3 id="step-2-update-penalty-interface-to-match-measurementpenalties-schema" tabindex="-1">Step 2: Update Penalty Interface to Match MeasurementPenalties Schema <a class="header-anchor" href="#step-2-update-penalty-interface-to-match-measurementpenalties-schema" aria-label="Permalink to &quot;Step 2: Update Penalty Interface to Match MeasurementPenalties Schema&quot;">​</a></h3><ul><li>Add <code>subjectName?: string</code> field to the reports item</li><li>Remove stale <code>subject</code> field (replaced by <code>subjectName</code>)</li><li>Rename <code>totalCount</code> to <code>total</code> in the <code>data</code> wrapper</li><li>Verify all remaining fields match the swagger <code>MeasurementPenalties</code> schema</li></ul><h3 id="step-3-update-measurement-interface-to-match-whm-schema" tabindex="-1">Step 3: Update Measurement Interface to Match WHM Schema <a class="header-anchor" href="#step-3-update-measurement-interface-to-match-whm-schema" aria-label="Permalink to &quot;Step 3: Update Measurement Interface to Match WHM Schema&quot;">​</a></h3><ul><li>Remove stale fields: <code>dateStart</code>, <code>dateEnd</code> (not in WHM schema)</li><li>Remove fields that belong only to MeasurementPenalties: <code>prcOver</code>, <code>volumeSup</code>, <code>widthSup</code>, <code>lengthSup</code>, <code>heightSup</code></li><li>Remove stale <code>subject</code> field, add <code>subjectName?: string</code></li><li>Rename <code>totalCount</code> to <code>total</code> in the <code>data</code> wrapper</li><li>Verify remaining fields: <code>nmId</code>, <code>dimId</code>, <code>volume</code>, <code>width</code>, <code>length</code>, <code>height</code>, <code>photoUrls</code>, <code>dt</code></li></ul><h3 id="step-4-add-response-types-for-promise-unknown-methods" tabindex="-1">Step 4: Add Response Types for Promise&lt;unknown&gt; Methods <a class="header-anchor" href="#step-4-add-response-types-for-promise-unknown-methods" aria-label="Permalink to &quot;Step 4: Add Response Types for Promise\\&lt;unknown\\&gt; Methods&quot;">​</a></h3><p>Create new interfaces for the 6 targeted methods (per task-43 AC #4):</p><ul><li><code>AntifraudDetailsResponse</code> for <code>getAnalyticsAntifraudDetails</code></li><li><code>GoodsLabelingResponse</code> for <code>getAnalyticsGoodsLabeling</code></li><li><code>RegionSaleResponse</code> for <code>getAnalyticsRegionSale</code></li><li><code>BrandShareBrandsResponse</code> for <code>getBrandShareBrands</code></li><li><code>BrandShareParentSubjectsResponse</code> for <code>getBrandShareParentSubjects</code></li><li><code>BrandShareResponse</code> for <code>getAnalyticsBrandShare</code></li></ul><p>Define fields based on swagger response schemas where available, or use best-effort typing from API documentation and examples.</p><h3 id="step-5-add-missing-error-types" tabindex="-1">Step 5: Add Missing Error Types <a class="header-anchor" href="#step-5-add-missing-error-types" aria-label="Permalink to &quot;Step 5: Add Missing Error Types&quot;">​</a></h3><p>Add <code>Response400Retentions</code> and <code>Response403Retentions</code> interfaces to <code>reports.types.ts</code> matching the swagger schemas:</p><ul><li>Both have: <code>title?: string</code>, <code>status?: number</code>, <code>detail?: string</code>, <code>requestId?: string</code>, <code>origin?: string</code></li></ul><h3 id="step-6-handle-stale-error-types" tabindex="-1">Step 6: Handle Stale Error Types <a class="header-anchor" href="#step-6-handle-stale-error-types" aria-label="Permalink to &quot;Step 6: Handle Stale Error Types&quot;">​</a></h3><p>Mark <code>Response400WHM</code> and <code>Response403WHM</code> with <code>@deprecated</code> tags since they are no longer in the current swagger. These may still be imported by consumer code, so removal would be a breaking change. Mark deprecated with a note pointing to <code>Response400Retentions</code>/<code>Response403Retentions</code>.</p><h3 id="step-7-extract-inline-type-literals-to-named-interfaces" tabindex="-1">Step 7: Extract Inline Type Literals to Named Interfaces <a class="header-anchor" href="#step-7-extract-inline-type-literals-to-named-interfaces" aria-label="Permalink to &quot;Step 7: Extract Inline Type Literals to Named Interfaces&quot;">​</a></h3><p>Extract the 5 inline object types into named interfaces:</p><ul><li><code>WarehouseRemainsDownloadItem</code> (8 fields + nested <code>warehouses</code> array)</li><li><code>AcceptanceReportDownloadItem</code> (7 fields)</li><li><code>BannedProductsBlockedResponse</code> (nested <code>report</code> array with 5 fields)</li><li><code>BannedProductsShadowedResponse</code> (nested <code>report</code> array with 5 fields)</li><li><code>GoodsReturnResponse</code> (nested <code>report</code> array with 19 fields)</li></ul><p>Update the corresponding method signatures and generic type parameters in <code>src/modules/reports/index.ts</code>.</p><h3 id="step-8-validate-type-safety" tabindex="-1">Step 8: Validate Type Safety <a class="header-anchor" href="#step-8-validate-type-safety" aria-label="Permalink to &quot;Step 8: Validate Type Safety&quot;">​</a></h3><p>Run <code>npx tsc --noEmit</code> to ensure zero TypeScript errors in strict mode across the entire project. Verify that all imports are resolved and no circular dependencies are introduced.</p><hr><h2 id="files-to-modify" tabindex="-1">Files to Modify <a class="header-anchor" href="#files-to-modify" aria-label="Permalink to &quot;Files to Modify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Changes</th><th>Estimated Effort</th></tr></thead><tbody><tr><td><code>src/types/reports.types.ts</code></td><td>Fix ExciseReportRequest.countries, update Penalty/Measurement, add error types, deprecate stale types, add response types for Promise&lt;unknown&gt; methods, extract inline types to named interfaces</td><td>High</td></tr><tr><td><code>src/modules/reports/index.ts</code></td><td>Update return types for 6 Promise&lt;unknown&gt; methods, replace 5 inline type literals with named interface references, update import statement</td><td>Medium</td></tr></tbody></table><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[ ] ExciseReportRequest.countries type fixed from malformed union to proper array: <code>(&#39;AM&#39; | &#39;BY&#39; | &#39;KG&#39; | &#39;KZ&#39; | &#39;RU&#39; | &#39;UZ&#39;)[]</code></li><li>[ ] Penalty interface updated to match MeasurementPenalties swagger schema (add <code>subjectName</code>, rename <code>totalCount</code> to <code>total</code>, remove stale <code>subject</code>, verify all fields)</li><li>[ ] Measurement interface updated to match WHM swagger schema (remove stale <code>dateStart</code>/<code>dateEnd</code>/<code>prcOver</code>/<code>volumeSup</code>/<code>widthSup</code>/<code>lengthSup</code>/<code>heightSup</code>/<code>subject</code>, add <code>subjectName</code>, rename <code>totalCount</code> to <code>total</code>)</li><li>[ ] 6 active methods with <code>Promise&lt;unknown&gt;</code> replaced with proper response types: <code>getAnalyticsAntifraudDetails</code>, <code>getAnalyticsGoodsLabeling</code>, <code>getAnalyticsRegionSale</code>, <code>getBrandShareBrands</code>, <code>getBrandShareParentSubjects</code>, <code>getAnalyticsBrandShare</code></li><li>[ ] <code>Response400Retentions</code> and <code>Response403Retentions</code> error types added from swagger</li><li>[ ] Stale <code>Response400WHM</code> and <code>Response403WHM</code> types marked <code>@deprecated</code> with migration guidance</li><li>[ ] 5 methods using inline object type literals refactored to named interfaces (<code>getTasksDownload</code> variants, <code>getBannedProducts</code> variants, <code>getAnalyticsGoodsReturn</code>)</li><li>[ ] All type changes pass TypeScript strict compilation with zero errors</li></ul><hr><h2 id="risk-assessment" tabindex="-1">Risk Assessment <a class="header-anchor" href="#risk-assessment" aria-label="Permalink to &quot;Risk Assessment&quot;">​</a></h2><p><strong>Risk Level: MEDIUM</strong></p><ul><li><strong>ExciseReportRequest.countries fix is a BREAKING CHANGE</strong>: Any code passing a bare string where the corrected array type is expected will fail to compile. This is intentional -- the old type was incorrect and did not match the API contract.</li><li><strong>Penalty <code>totalCount</code> to <code>total</code> rename is a BREAKING CHANGE</strong>: Consumers reading <code>data.totalCount</code> must update to <code>data.total</code>. The old field name was incorrect per the API response.</li><li><strong>Measurement field removals are BREAKING CHANGES</strong>: Removing <code>dateStart</code>, <code>dateEnd</code>, <code>prcOver</code>, <code>volumeSup</code>, <code>widthSup</code>, <code>lengthSup</code>, <code>heightSup</code>, and <code>subject</code> will break any code referencing these fields. However, these fields were never populated by the API (they do not exist in the WHM schema), so consumers using them were already getting <code>undefined</code>.</li><li><strong>Adding <code>subjectName</code> to both types is non-breaking</strong>: Additive field addition.</li><li><strong>Adding new response types is non-breaking</strong>: <code>AntifraudDetailsResponse</code>, <code>GoodsLabelingResponse</code>, etc. are additive changes.</li><li><strong>Adding error types is non-breaking</strong>: <code>Response400Retentions</code> and <code>Response403Retentions</code> are additive.</li><li><strong>Deprecating stale types is non-breaking</strong>: <code>Response400WHM</code> and <code>Response403WHM</code> are marked deprecated but not removed.</li><li><strong>Extracting inline types is technically breaking</strong>: If any consumer imports the module type and relies on the exact inline shape via structural typing, the change to a named interface is structurally compatible but the import path changes. In practice, this is non-breaking since the shapes are preserved.</li></ul><p><strong>Mitigation</strong>: Document all breaking changes in the release notes with migration examples. Bump minor version to signal potentially breaking type corrections.</p><hr><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><strong>Depends on</strong>: None (standalone type fixes)</li><li><strong>Blocks</strong>: task-44 (Reports New &amp; Removed Endpoints -- 3 new deductions endpoints, 3 stale removals, @deprecated marking), task-45 (Reports Code Quality -- JSDoc, Rate Limits, Tests, Config Cleanup)</li></ul><hr><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Path</th></tr></thead><tbody><tr><td>Swagger spec</td><td><code>wildberries_api_doc/12-reports.yaml</code></td></tr><tr><td>Module source</td><td><code>src/modules/reports/index.ts</code> (507 lines, 26 methods)</td></tr><tr><td>Types file</td><td><code>src/types/reports.types.ts</code> (479 lines, 18 interfaces + 2 type aliases)</td></tr><tr><td>Rate limits config</td><td><code>src/config/reports-rate-limits.ts</code> (147 lines)</td></tr><tr><td>Story 3.7</td><td><code>docs/stories/3.7.reports-generation-retrieval.md</code></td></tr><tr><td>Story 4.4</td><td><code>docs/stories/4.4.reports-generation-retrieval.md</code></td></tr><tr><td>QA Gate 3.7</td><td><code>docs/qa/gates/3.7-reports-generation-retrieval.yml</code></td></tr><tr><td>QA Gate 4.4</td><td><code>docs/qa/gates/4.4-reports-generation-retrieval.yml</code></td></tr><tr><td>EPIC 41 (analytics analog)</td><td><code>docs/epics/EPIC_41_ANALYTICS_TYPE_SCHEMA_FIXES.md</code></td></tr><tr><td>EPIC 44 (reports endpoints)</td><td>task-44 (Reports New &amp; Removed Endpoints)</td></tr><tr><td>EPIC 45 (reports quality)</td><td>task-45 (Reports Code Quality)</td></tr><tr><td>Backlog task</td><td><code>backlog/tasks/task-43</code></td></tr></tbody></table>',70)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
